import json
for qformat in ['EXL3', 'exl3']:
    module_dict={'stored_tensors': {'layer.trellis': {'shape': [1,48]}}}
    if qformat == 'EXL3':
        shape=module_dict['stored_tensors']['layer.trellis']['shape']
        module_dict['quant_format']='exl3'
        module_dict['bits_per_weight']=shape[-1]//16
    print(qformat, json.dumps(module_dict,sort_keys=True))

